/**
 * Method that can be called to get the next token, if any; if no next
 * token is available, returns null.
 */
@Override
public JsonToken nextToken() throws IOException {
    // Let's verify if the current token is incomplete
    if (_tokenIncomplete) {
        // If so, we need to complete it before moving to the next token
        return _finishToken();
    }
    // Otherwise, let's prepare for reading the next token
    _numTypesValid = NR_UNKNOWN;
    _tokenInputTotal = _currInputProcessed + _inputPtr;
    _binaryValue = null;

    // Main parsing loop
    while (true) {
        if (_inputPtr >= _inputEnd) {
            if (!_loadMore()) {
                // If there is no more content to load, we are done
                _handleEOF();
                return (_currToken = null);
            }
        }
        int ch = _inputBuffer[_inputPtr++];
        // Skip white spaces
        if (ch <= INT_SPACE) {
            if (ch != INT_SPACE) {
                if (ch == INT_LF) {
                    _currInputRow++;
                    _currInputRowStart = _inputPtr;
                } else if (ch == INT_CR) {
                    _currInputRow++;
                    _currInputRowStart = _inputPtr;
                    if (_inputPtr < _inputEnd || _loadMore()) {
                        if (_inputBuffer[_inputPtr] == INT_LF) {
                            _inputPtr++;
                        }
                    }
                } else if (ch != INT_TAB) {
                    _throwInvalidSpace(ch);
                }
            }
        } else {
            if (ch == INT_SLASH) {
                _skipComment();
                continue;
            }
            return _handleToken(ch);
        }
    }
}
